import{_ as t,o as a,c as r,ag as i}from"./chunks/framework.BuUvxvtQ.js";const u=JSON.parse('{"title":"API Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/api-dashboard.md","filePath":"web-app/api-dashboard.md"}'),o={name:"web-app/api-dashboard.md"};function s(n,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="api-dashboard" tabindex="-1">API Dashboard <a class="header-anchor" href="#api-dashboard" aria-label="Permalink to &quot;API Dashboard&quot;">​</a></h1><p>The <strong>API Dashboard</strong> (<code>/dashboard/api</code>) is the full key-management surface for the <a href="./../api/">public API</a>. It sits at the intersection of the web app and the API — manage keys, group them, and allocate credits to them.</p><h2 id="managing-keys" tabindex="-1">Managing keys <a class="header-anchor" href="#managing-keys" aria-label="Permalink to &quot;Managing keys&quot;">​</a></h2><ul><li><strong>Create</strong> <code>sk_live_</code> API keys — the full key is shown <strong>only once</strong> at creation, so copy it immediately.</li><li><strong>Name</strong> keys with a nickname for easy identification.</li><li><strong>Group</strong> keys into folders to organise them (e.g. &quot;Production&quot;, &quot;Testing&quot;).</li><li><strong>Revoke</strong> any key instantly. Revoked keys immediately stop authenticating.</li><li>View each key&#39;s preview, folder, creation date, and active/revoked status.</li></ul><h2 id="active-key-limits" tabindex="-1">Active key limits <a class="header-anchor" href="#active-key-limits" aria-label="Permalink to &quot;Active key limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plan</th><th>Active keys</th></tr></thead><tbody><tr><td>Free</td><td>3</td></tr><tr><td>Pro</td><td>20</td></tr><tr><td>Dev</td><td>Unlimited</td></tr></tbody></table><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>Sky Style keeps three balances distinct. The API Dashboard is where you move value between them:</p><table tabindex="0"><thead><tr><th>Balance</th><th>Use</th></tr></thead><tbody><tr><td><strong>$ Credit (AUD)</strong></td><td>Convert $1.00 into 50 API Credit for a key you choose. Pro receives $1.00 each calendar month.</td></tr><tr><td><strong>API Credit</strong></td><td>Per-key balance consumed by public API requests.</td></tr><tr><td><strong>App Credit</strong></td><td>In-app balance, including developer gifts and API fallback when a key&#39;s API Credit is empty. Pro receives 50 App Credits each day.</td></tr></tbody></table><h3 id="allocating-credit" tabindex="-1">Allocating credit <a class="header-anchor" href="#allocating-credit" aria-label="Permalink to &quot;Allocating credit&quot;">​</a></h3><p>When you have at least <strong>$1.00</strong> in $ Credit and at least one active API key:</p><ol><li>Select a key from the dropdown (shown with its folder and nickname).</li><li>Click <strong>Allocate $1 → 50 API Credit</strong>.</li><li>The selected key&#39;s API Credit balance increases by 50.</li></ol><div class="warning custom-block"><p class="custom-block-title">Purchases not live yet</p><p>API credit purchases are not live yet. The app&#39;s &quot;Get credits&quot; button currently opens an informational donation prompt — it does not process a purchase. App Credit can be gifted by a developer in the meantime.</p></div><h2 id="app-credit-fallback" tabindex="-1">App Credit fallback <a class="header-anchor" href="#app-credit-fallback" aria-label="Permalink to &quot;App Credit fallback&quot;">​</a></h2><p>When an API key&#39;s API Credit balance is empty, Sky Style automatically uses one available App Credit for the request and returns an <code>X-Credit-Warning</code> header so API clients can surface the fallback. See <a href="./../api/errors.html">Errors &amp; Credits</a> for the full charging rules.</p><h2 id="tutorials" tabindex="-1">Tutorials <a class="header-anchor" href="#tutorials" aria-label="Permalink to &quot;Tutorials&quot;">​</a></h2><p>The API Dashboard has its own guided tour — replay it from <a href="./settings.html#tutorials">Settings → Tutorials</a>.</p>',17)])])}const b=t(o,[["render",s]]);export{u as __pageData,b as default};
